package com.lexorion.workforce.repository;import com.lexorion.workforce.domain.WorkforceWorkspace;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface WorkforceWorkspaceRepository extends JpaRepository<WorkforceWorkspace,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select w from WorkforceWorkspace w where w.id=:id")Optional<WorkforceWorkspace> findByIdForUpdate(@Param("id")UUID id);}
